def evaluate(current_reputation, observation, my_history, round_num):
    # Apply reputation decay to give more weight to recent interactions
    decay = 0.95 if round_num > 2 else 1.0
    if observation["action"] == "cooperate":
        # Higher reward for cooperation, weighted by decay
        new_reputation = current_reputation * decay + 0.7
    else:
        # Higher penalty for defection
        new_reputation = current_reputation * decay - 0.6
    # Clamp reputation to reasonable range
    new_reputation = max(-10.0, min(10.0, new_reputation))
    return new_reputation

def decide(recipient_reputation, round_num, my_history):
    # Adjust threshold based on round number and own history
    if round_num <= 5:
        # Early rounds: more trusting
        return recipient_reputation >= -0.5
    elif round_num <= 15:
        # Mid rounds: moderate threshold
        return recipient_reputation >= 0.0
    else:
        # Later rounds: more selective
        return recipient_reputation >= 0.5
